import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, type Claim } from '../claims/claimsQuery';
import { policyOn, usePolicyVersionLines, usePolicyVersions } from '../settings/settingsQuery';

/** The sheet's current policy version: how many versions of its policy settings have been made. */
function PolicyVersion({ sheetId }: { sheetId: string }) {
  return (
    <p data-testid="policy-version-panel">
      Policy version <strong data-testid="policy-version">{usePolicyVersions(sheetId).length}</strong>
    </p>
  );
}

/** The policy versions, oldest first, once shown: "<version> <from or start> <key>=<value> <claims under it>". */
function PolicyViewer({ sheetId }: { sheetId: string }) {
  const [shown, setShown] = useState(false);
  const versions = usePolicyVersions(sheetId);
  const lines = usePolicyVersionLines(sheetId);
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const under = new Map<number, number>();
  for (const claim of claims) {
    const no = policyOn(versions, claim.date);
    under.set(no, (under.get(no) ?? 0) + 1);
  }
  return (
    <section data-testid="policy-viewer">
      <button type="button" data-testid="policy-show" onClick={() => setShown(true)}>
        Show policy versions
      </button>
      {shown && (
        <ol data-testid="policy-lines">
          {lines.map((v, i) => (
            <li key={i} data-testid="policy-line">
              {`${i + 1} ${v.from ?? 'start'} ${v.key}=${v.value} ${under.get(i + 1) ?? 0}`}
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

/** The policy version in force on the claim's date. */
function ClaimPolicy({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-policy">{policyOn(usePolicyVersions(sheetId), claim.date)}</td>;
}

export const contributions = [
  SheetPanel.fill({ order: 25.6, Component: PolicyVersion }),
  SheetPanel.fill({ order: 25.7, Component: PolicyViewer }),
  ClaimCells.fill({ order: 10.5, Component: ClaimPolicy }),
];
import { useQueryClient } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { ratesQuery } from '../rates/ratesQuery';
import { useFloor, useLate } from '../settings/settingsQuery';
import { personPeriodCarried, personPeriodDue, periodsQuery } from './periodsQuery';

/** Downloads the period figures as CSV: one line per person and period, people in list order (retired people included)
 *  and periods in the order added, with each person's due-total and carried figure for the period as their row shows
 *  them. The data is re-read first, so the file holds what the store holds now. */
function ExportPeriods({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const exportCsv = async () => {
    const fresh = { staleTime: 0 };
    const [periods, people, claims, rates] = await Promise.all([
      queryClient.fetchQuery({ ...periodsQuery(sheetId), ...fresh }),
      queryClient.fetchQuery({ ...peopleQuery(sheetId), ...fresh }),
      queryClient.fetchQuery({ ...claimsQuery(sheetId), ...fresh }),
      queryClient.fetchQuery({ ...ratesQuery(sheetId), ...fresh }),
    ]);
    const added = [...periods].sort((a, b) => a.added - b.added);
    downloadCsv('periods.csv', [
      ['person', 'period', 'figure', 'carried'],
      ...people.flatMap((person) =>
        added.map((p) => [
          person.name,
          p.name,
          personPeriodDue(p, person, claims, people, rates, floor, late),
          personPeriodCarried(p, periods, person, claims, people, rates, floor, late),
        ]),
      ),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-periods" onClick={() => void exportCsv()}>
        Export period figures (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 7.1, Component: ExportPeriods });
/** A CSV value: wrapped in double quotes, with inner quotes doubled, when it holds a comma, a quote or a line break. */
export function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** Downloads the rows (each a list of values) as a CSV file, every line ending in "\n". */
export function downloadCsv(fileName: string, rows: string[][]): void {
  const text = rows.map((r) => r.map(csvValue).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([text], { type: 'text/csv' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
