content.content:
 * the grade its person had on that date (rounded by the policy date, see `roundsHalfUp`), raised to the sheet's `floor` in force on the claim's date (two decimals).
 * An overdue claim's late charge — for every full 30 days overdue, the late percent in force on that boundary date (the due-by plus the grace plus 30, 60, 90 ... days)
 * of that floored figure plus the charges of the boundaries before it (compounding), each rounded like the claim, added up — is then added on top, following the sheet's today.
 * A correction has neither floor nor late charge.
 */
export function figure(claim: Claim, rates: Rate[], person: Person | undefined, floor: DatedValue[], late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  if (claim.stated) return claim.statedDue ?? 'n/a';
  const halfUp = roundsHalfUp(claim, late);
  const bound = due(claim.amount, rateFor(rates, gradeOn(person, claim.date), claim.date, claim.id), halfUp);
  if (isCorrection(claim) || bound === 'n/a') return bound;
  const months = lateMonths(claim, late);
  const from = overdueFrom(claim, late);
  let total = hundredths(floored(bound, valueOn(floor, claim.date) ?? DEFAULT_FLOOR));
  for (let n = 1n; n <= months; n++) {
    total += dueCents(show(total), valueOn(late.pct, addDays(from, Number(n) * 30)) ?? DEFAULT_LATE_PCT, halfUp);
  }
  return show(total);
}

function floored(live: string, floor: string): string {
  return live === 'n/a' || hundredths(live) >= hundredths(floor) ? live : show(hundredths(floor));
}

/**
 * The holder's part of a claim's figure: the figure times their share percent divided by 100, rounded half to even
 * (n/a when the figure is). How a settled claim's parts stay frozen.
 */
export function sharePart(figure: string, share: string): string {
  return figure === 'n/a' ? 'n/a' : sumOfShares([[figure, share]]);
}

/**
 * The holder's part of an unsettled claim: its amount times their share divided by 100, times the rate of the holder's
 * own grade in force on the claim's date divided by 100, rounded like the claim (see `roundsHalfUp`); n/a when their
 * grade has no rate (it counts as 0.00 against the claim's own person).
 */
export function holderPart(claim: Claim, holder: Person | undefined, share: string, rates: Rate[], late: Late): string {
  const rate = rateFor(rates, gradeOn(holder, claim.date), claim.date, claim.id);
  if (rate === undefined) return 'n/a';
  const signed = hundredths(claim.amount) * hundredths(share) * hundredths(rate);
  const product = signed < 0n ? -signed : signed;
  const cents = product / 100000000n;
  const rest = product % 100000000n;
  const rounded = rest > 50000000n || (rest === 50000000n && (roundsHalfUp(claim, late) || cents % 2n === 1n)) ? cents + 1n : cents;
  return show(signed < 0n ? -rounded : rounded);
}

/**
 * What the person counts of the claim's figure (null when it is neither theirs nor shared with them): a holder their
 * part (see `holderPart`; a settled claim's frozen parts see `sharePart`), the claim's own person the figure less every
 * holder's part. The figure is worked out for the claim's own person.
 */
export function personPart(claim: Claim, person: Person, people: Person[], rates: Rate[], floor: DatedValue[], late: Late): string | null {
  const own = claim.personId === person.id;
  const holding = own ? undefined : claim.shares.find((s) => s.personId === person.id);
  if (!own && !holding) return null;
  const whole = figure(claim, rates, people.find((p) => p.id === claim.personId), floor, late);
  const part = (s: ClaimShare) => claim.status === 'SETTLED'
    ? sharePart(whole, s.share)
    : holderPart(claim, people.find((p) => p.id === s.personId), s.share, rates, late);
  if (holding) return part(holding);
  if (whole === 'n/a') return whole;
  return difference(whole, sumDue(claim.shares.map(part)));
}

/**
 * A person's figures added up, before the cap: the sum of what they count (see `personPart`) of their own counting
 * claims' rounded figures, as each claim shows it, and of those shared with them. With no rate today and no figure it is n/a; otherwise it is the sum of the figures there are.
 */
export function personSum(person: Person | undefined, people: Person[], claims: Claim[], rates: Rate[], today: string, floor: DatedValue[], late: Late): string {
  if (!person) return 'n/a';
  const rate = rateFor(rates, gradeOn(person, today), today);
  const figures = claims
    .filter((c) => counts(c, people, today))
    .map((c) => personPart(c, person, people, rates, floor, late))
    .filter((d): d is string => d !== null && d !== 'n/a');
  return rate === undefined && figures.length === 0 ? 'n/a' : sumDue(figures);
}

